{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Spec Rules 0.2.0 — envelope e assinatura",
  "type": "object",
  "minProperties": 1,
  "maxProperties": 1,
  "patternProperties": {
    "^[A-Z][A-Z0-9-]*-[0-9]{3,}$": {
      "type": "object",
      "required": [
        "formato",
        "versao",
        "modulo",
        "estado",
        "entrada",
        "saida",
        "fluxo",
        "excecoes"
      ],
      "properties": {
        "formato": {
          "const": "a-bioma-spec-rules"
        },
        "versao": {
          "const": "0.2.0"
        },
        "modulo": {
          "type": "string",
          "minLength": 1
        },
        "estado": {
          "enum": [
            "proposta",
            "em refinamento",
            "refinado"
          ]
        },
        "entrada": {
          "oneOf": [
            {
              "type": "object",
              "required": [
                "nome",
                "doc"
              ],
              "properties": {
                "nome": {
                  "type": "string",
                  "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
                },
                "doc": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "additionalProperties": false
            },
            {
              "type": "object",
              "minProperties": 1,
              "patternProperties": {
                "^(?!nome$|doc$)[A-Za-z_][A-Za-z0-9_]*$": {
                  "type": "object",
                  "required": [
                    "doc"
                  ],
                  "properties": {
                    "doc": {
                      "type": "string",
                      "minLength": 1
                    }
                  },
                  "additionalProperties": false
                }
              },
              "additionalProperties": false
            }
          ]
        },
        "saida": {
          "type": "object",
          "required": [
            "doc"
          ],
          "properties": {
            "doc": {
              "type": "string",
              "minLength": 1
            }
          },
          "additionalProperties": false
        },
        "fluxo": {
          "type": "object",
          "required": [
            "atores",
            "root"
          ],
          "properties": {
            "atores": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "object",
                "required": [
                  "ator"
                ],
                "properties": {
                  "ator": {
                    "type": "string",
                    "minLength": 1
                  }
                },
                "additionalProperties": true
              }
            },
            "root": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "object",
                "required": [
                  "id",
                  "acao"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "minLength": 1
                  },
                  "acao": {
                    "enum": [
                      "validar",
                      "decidir",
                      "chamar",
                      "operar",
                      "atribuir",
                      "acrescentar",
                      "repetir",
                      "calcular",
                      "retornar",
                      "falhar"
                    ]
                  }
                },
                "additionalProperties": true
              }
            }
          },
          "additionalProperties": false
        },
        "excecoes": {
          "type": "array",
          "items": {
            "type": "object"
          }
        },
        "sem_excecoes": {
          "type": "string",
          "minLength": 1
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "excecoes": {
                "maxItems": 0
              }
            }
          },
          "then": {
            "required": [
              "sem_excecoes"
            ]
          }
        }
      ],
      "additionalProperties": true
    }
  },
  "additionalProperties": false
}

