{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Spec Rules — contrato com campos recursivos",
  "type": "object",
  "minProperties": 1,
  "maxProperties": 1,
  "patternProperties": {
    "^CONTR-[0-9]{3,}$": {
      "type": "object",
      "required": [
        "formato",
        "versao",
        "tipo_documento",
        "modulo",
        "estado",
        "campos",
        "nome"
      ],
      "properties": {
        "formato": {
          "const": "a-bioma-spec-rules"
        },
        "versao": {
          "const": "0.2.0"
        },
        "tipo_documento": {
          "const": "contrato"
        },
        "modulo": {
          "type": "string"
        },
        "estado": {
          "enum": [
            "proposta",
            "em refinamento",
            "refinado"
          ]
        },
        "campos": {
          "$ref": "#/$defs/campos"
        },
        "nome": {
          "type": "string",
          "minLength": 1
        },
        "descricao": {
          "type": "string",
          "minLength": 1
        },
        "objetivo": {
          "type": "string",
          "minLength": 1
        },
        "implementacao": {
          "enum": [
            "nao implementado",
            "implementado",
            "nao verificado"
          ]
        },
        "pendencias": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "referencias": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^(?:[A-Z][A-Z0-9-]*-[0-9]{3,}|@[A-Z][A-Z0-9-]*-[0-9]{3,}|@\\[[a-z][a-z0-9_-]*\\]\\([A-Z][A-Z0-9-]*-[0-9]{3,}\\))$"
          }
        }
      },
      "allOf": [
        {
          "not": {
            "anyOf": [
              {
                "required": [
                  "contratos"
                ]
              },
              {
                "required": [
                  "fluxo"
                ]
              },
              {
                "required": [
                  "atores"
                ]
              },
              {
                "required": [
                  "root"
                ]
              },
              {
                "required": [
                  "passos"
                ]
              },
              {
                "required": [
                  "efeitos"
                ]
              }
            ]
          }
        }
      ],
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "$defs": {
    "campos": {
      "type": "object",
      "propertyNames": {
        "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
      },
      "additionalProperties": {
        "$ref": "#/$defs/campo"
      }
    },
    "campo": {
      "type": "object",
      "required": [
        "id",
        "tipo",
        "obrigatorio"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^CMP-[0-9]{4,}$"
        },
        "tipo": {
          "anyOf": [
            {
              "enum": [
                "texto",
                "inteiro",
                "decimal",
                "booleano",
                "data",
                "data_hora",
                "binario",
                "objeto",
                "lista"
              ]
            },
            {
              "type": "string",
              "pattern": "^(?:[A-Z][A-Z0-9-]*-[0-9]{3,}|@[A-Z][A-Z0-9-]*-[0-9]{3,}|@\\[[a-z][a-z0-9_-]*\\]\\([A-Z][A-Z0-9-]*-[0-9]{3,}\\))$"
            }
          ]
        },
        "obrigatorio": {
          "type": "boolean"
        },
        "descricao": {
          "type": "string",
          "minLength": 1
        },
        "subcampos": {
          "$ref": "#/$defs/campos"
        },
        "doc": {
          "type": "string",
          "pattern": "^(?:[A-Z][A-Z0-9-]*-[0-9]{3,}|@[A-Z][A-Z0-9-]*-[0-9]{3,}|@\\[[a-z][a-z0-9_-]*\\]\\([A-Z][A-Z0-9-]*-[0-9]{3,}\\))$"
        },
        "itens": {
          "$ref": "#/$defs/elemento"
        },
        "regras": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^(?:[A-Z][A-Z0-9-]*-[0-9]{3,}|@[A-Z][A-Z0-9-]*-[0-9]{3,}|@\\[[a-z][a-z0-9_-]*\\]\\([A-Z][A-Z0-9-]*-[0-9]{3,}\\))$"
          }
        },
        "restricoes": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "tipo": {
                "const": "objeto"
              }
            }
          },
          "then": {
            "oneOf": [
              {
                "required": [
                  "subcampos"
                ],
                "not": {
                  "required": [
                    "doc"
                  ]
                }
              },
              {
                "required": [
                  "doc"
                ],
                "not": {
                  "required": [
                    "subcampos"
                  ]
                }
              }
            ]
          },
          "else": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "subcampos"
                  ]
                },
                {
                  "required": [
                    "doc"
                  ]
                }
              ]
            }
          }
        },
        {
          "if": {
            "properties": {
              "tipo": {
                "const": "lista"
              }
            }
          },
          "then": {
            "required": [
              "itens"
            ]
          },
          "else": {
            "not": {
              "required": [
                "itens"
              ]
            }
          }
        }
      ],
      "additionalProperties": false
    },
    "elemento": {
      "type": "object",
      "required": [
        "tipo"
      ],
      "properties": {
        "tipo": {
          "$ref": "#/$defs/campo/properties/tipo"
        },
        "subcampos": {
          "$ref": "#/$defs/campos"
        },
        "doc": {
          "type": "string",
          "pattern": "^(?:[A-Z][A-Z0-9-]*-[0-9]{3,}|@[A-Z][A-Z0-9-]*-[0-9]{3,}|@\\[[a-z][a-z0-9_-]*\\]\\([A-Z][A-Z0-9-]*-[0-9]{3,}\\))$"
        },
        "itens": {
          "$ref": "#/$defs/elemento"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "tipo": {
                "const": "objeto"
              }
            }
          },
          "then": {
            "oneOf": [
              {
                "required": [
                  "subcampos"
                ],
                "not": {
                  "required": [
                    "doc"
                  ]
                }
              },
              {
                "required": [
                  "doc"
                ],
                "not": {
                  "required": [
                    "subcampos"
                  ]
                }
              }
            ]
          },
          "else": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "subcampos"
                  ]
                },
                {
                  "required": [
                    "doc"
                  ]
                }
              ]
            }
          }
        },
        {
          "if": {
            "properties": {
              "tipo": {
                "const": "lista"
              }
            }
          },
          "then": {
            "required": [
              "itens"
            ]
          },
          "else": {
            "not": {
              "required": [
                "itens"
              ]
            }
          }
        }
      ],
      "additionalProperties": false
    }
  }
}
